/**
 * Type conformance. Asserts that the hand-written public types agree with the generated OpenAPI
 * schema types (`src/generated/types.ts`, regenerated by `npm run codegen` from
 * `openapi/openapi.yaml`): every REQUEST the SDK sends is a valid spec request (public → schema),
 * every RESPONSE the spec allows is assignable to the public type (schema → public, so the public
 * types never promise less than the contract), and the public types declare every schema field. Each assertion
 * fails to compile on drift (a missing field, a widened enum, a wrong shape), so `npm run typecheck`
 * catches it. Type-only: nothing here runs; this file is intentionally not a `*.test.ts`.
 */

import type { components } from '../src/generated/types.js';
import type { ModelDetail, KeyInfo, EvalRunList, ImprovementReads } from '../src/resources.js';
import type {
  AutopilotStatus,
  BenchDatasetFreeze,
  BenchExpectationInput,
  BenchExpectations,
  BenchOutcomeInput,
  BenchOutcomes,
  BenchReport,
  BenchRun,
  BenchRunParams,
  BenchRunTrigger,
  BenchSuiteStatus,
  CallType,
  CallTypeConfigBody,
  ChatCompletion,
  ChatCompletionCreateParams,
  CreateCallTypeParams,
  CreateEmbeddingResponse,
  EmbeddingCreateParams,
  EnqueueEvalParams,
  EnqueueEvalResponse,
  Feedback,
  FeedbackEnvelope,
  FeedbackParams,
  GenerationStats,
  Model,
  ModelsListResponse,
  CallTypeConfigVersion,
  ChatMessage,
  UrRequestOptions,
  UrResponseBlock,
} from '../src/types.js';
import type {
  Artifact,
  ArtifactEnvelope,
  ArtifactListResponse,
  CreateArtifactParams,
  FinalParams,
  FinalResponse,
} from '../src/artifacts.js';
import type {
  BatchOutcomeInput,
  BatchOutcomesResponse,
  OutcomeInput,
  OutcomeResult,
  PendingClaimsResponse,
  RecordOutcomesResponse,
} from '../src/outcomes.js';
import type { UrManifest } from '../src/types.js';
import type { FlywheelStatus, FlywheelUsage } from '../src/flywheel-status.js';
import type {
  Import,
  ImportCapabilityReport,
  ImportEnvelope,
  ImportListResponse,
  ImportParams,
} from '../src/imports.js';
import type {
  PreflightGrant,
  PreflightKnowledge,
  PreflightParams,
  PreflightResponse,
  PreflightRouting,
} from '../src/preflight.js';

type Schemas = components['schemas'];

// ─── completeness: every field the schema declares exists on the hand-written type ───
type MissingKeys<Gen, Hand> = Exclude<keyof Gen, keyof Hand>;
type AssertNone<T extends never> = T;
type Element<A> = A extends readonly (infer E)[] ? E : never;
export type CompleteChatRequest = AssertNone<
  MissingKeys<Schemas['ChatCompletionsRequest'], ChatCompletionCreateParams>
>;
export type CompleteChatMessage = AssertNone<
  MissingKeys<Element<Schemas['ChatCompletionsRequest']['messages']>, ChatMessage>
>;
export type CompleteUrRequest = AssertNone<
  MissingKeys<NonNullable<Schemas['ChatCompletionsRequest']['ur']>, UrRequestOptions>
>;
export type CompleteChatResponse = AssertNone<
  MissingKeys<Schemas['ChatCompletionsResponse'], ChatCompletion>
>;
export type CompleteUrResponse = AssertNone<
  MissingKeys<Schemas['UrResponseBlock'], UrResponseBlock>
>;
export type CompleteEmbeddingRequest = AssertNone<
  MissingKeys<Schemas['EmbeddingsRequest'], EmbeddingCreateParams>
>;
export type CompleteEmbeddingResponse = AssertNone<
  MissingKeys<Schemas['EmbeddingsResponse'], CreateEmbeddingResponse>
>;
export type CompleteModel = AssertNone<
  MissingKeys<Element<Schemas['ModelsListResponse']['data']>, Model>
>;
export type CompleteCallType = AssertNone<MissingKeys<Schemas['CallTypeSummary'], CallType>>;
export type CompleteCallTypeVersion = AssertNone<
  MissingKeys<NonNullable<Schemas['CallTypeSummary']['config']>, CallTypeConfigVersion>
>;
export type CompleteCallTypeConfig = AssertNone<
  MissingKeys<Schemas['CallTypeConfigBody'], CallTypeConfigBody>
>;
export type CompleteCreateCallType = AssertNone<
  MissingKeys<Schemas['CreateCallTypeRequest'], CreateCallTypeParams>
>;
export type CompleteFeedbackRequest = AssertNone<
  MissingKeys<Schemas['FeedbackRequest'], FeedbackParams>
>;
export type CompleteFeedback = AssertNone<MissingKeys<Schemas['FeedbackResponse'], Feedback>>;
export type CompleteGeneration = AssertNone<
  MissingKeys<Schemas['GenerationStats'], GenerationStats>
>;
export type CompleteAutopilot = AssertNone<
  MissingKeys<Schemas['AuditReadinessResponse'], AutopilotStatus>
>;
export type CompleteBenchRun = AssertNone<
  MissingKeys<Schemas['BenchRunTriggerRequest'], BenchRunParams>
>;

// ─── nullable values: the schema types them precisely, never as `unknown` ───
// The specification writes a nullable value as `{ type, nullable: true }` or as a nullable
// composition, so each generates as its declared type plus `null`. A field that regressed to
// `unknown` would make the assignments below vacuous, so these pin the generated types themselves.
type IsUnknown<T> = unknown extends T ? true : false;
type Equals<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type AssertTrue<T extends true> = T;
type AssertFalse<T extends false> = T;
type SpecChoice = Element<Schemas['ChatCompletionsResponse']['choices']>;
type SpecChatContent = Element<Schemas['ChatCompletionsRequest']['messages']>['content'];
type SpecPreflightContent = Element<
  NonNullable<Schemas['PreflightRequest']['messages']>
>['content'];
type SpecRunSpec = Element<Schemas['EvalRunListResponse']['data']>['run_spec'];
export type TypedFinishReason = AssertTrue<Equals<SpecChoice['finish_reason'], string | null>>;
export type TypedResponseContent = AssertTrue<
  Equals<Exclude<SpecChoice['message']['content'], undefined>, string | null>
>;
export type TypedChatContent = AssertFalse<IsUnknown<SpecChatContent>>;
export type NullableChatContent = AssertTrue<Equals<Extract<SpecChatContent, null>, null>>;
export type StringChatContent = AssertTrue<Equals<Extract<SpecChatContent, string>, string>>;
export type SamePreflightContent = AssertTrue<Equals<SpecPreflightContent, SpecChatContent>>;
export type TypedRunSpec = AssertFalse<IsUnknown<SpecRunSpec>>;
export type NullableRunSpec = AssertTrue<Equals<Extract<SpecRunSpec, null>, null>>;
// `preflight()` takes the same message objects as `chat.completions.create`.
export type PreflightMessagesAreChatMessages = AssertTrue<
  Equals<NonNullable<PreflightParams['messages']>, ChatMessage[]>
>;

/** Never called — the assignments are the compile-time conformance assertions. */
export function __conformance(): void {
  // requests: everything the SDK SENDS is a valid spec request. `model` is optional
  // at the call site (resolved from the init `defaultModel`); the spec requires it on
  // the wire, so conformance is asserted with `model` present — exactly what the SDK
  // sends after `applyChatDefaults` / `applyEmbeddingDefaults`.
  // `ur.manifest` also accepts the read-only value `toWire()` returns; on the wire it is the same JSON.
  const chatReq: Schemas['ChatCompletionsRequest'] = {} as Omit<
    ChatCompletionCreateParams,
    'ur'
  > & {
    model: string;
    ur?: Omit<UrRequestOptions, 'manifest'> & { manifest?: UrManifest };
  };
  const embedReq: Schemas['EmbeddingsRequest'] = {} as Omit<EmbeddingCreateParams, 'ur'> & {
    model: string;
    ur?: Omit<UrRequestOptions, 'manifest'> & { manifest?: UrManifest };
  };
  const feedbackReq: Schemas['FeedbackRequest'] = {} as FeedbackParams;
  const callTypeReq: Schemas['CreateCallTypeRequest'] = {} as CreateCallTypeParams;
  const callTypeCfg: Schemas['CallTypeConfigBody'] = {} as CallTypeConfigBody;
  // — the enqueue request/response are ALIASED from the generated schemas (bidirectional
  // identity), so a drift in the /v1/call-types/{id}/evals contract fails the typecheck.
  const enqueueEvalReq: Schemas['EnqueueEvalRequest'] = {} as EnqueueEvalParams;
  const enqueueEvalResp: Schemas['EnqueueEvalResponse'] = {} as EnqueueEvalResponse;
  // — the DEDUPE branch (`enqueued:false`) carries `prior_run_id` + `trigger`/`status` (all
  // `string | undefined`), so a client can follow the run it deduped onto. Narrowed here at compile time.
  const dedupeBranch = {} as EnqueueEvalResponse;
  const priorRunId: string | undefined =
    dedupeBranch.enqueued === false ? dedupeBranch.prior_run_id : undefined;
  const priorTrigger: string | undefined =
    dedupeBranch.enqueued === false ? dedupeBranch.trigger : undefined;
  const priorStatus: string | undefined =
    dedupeBranch.enqueued === false ? dedupeBranch.status : undefined;

  // responses: everything the SDK RETURNS is a valid spec response.
  const chatResp: Schemas['ChatCompletionsResponse'] = {} as ChatCompletion;
  const embedResp: Schemas['EmbeddingsResponse'] = {} as CreateEmbeddingResponse;
  const models: Schemas['ModelsListResponse'] = {} as ModelsListResponse;
  const feedback: Schemas['FeedbackResponse'] = {} as Feedback;
  // The feedback route returns the `{ feedback: … }` envelope; the SDK unwraps it.
  const feedbackEnvelope: Schemas['FeedbackEnvelope'] = {} as FeedbackEnvelope;
  const generation: Schemas['GenerationStats'] = {} as GenerationStats;
  const callType: Schemas['CallTypeSummary'] = {} as CallType;
  // Ur.autopilot.status() returns the spec's AuditReadinessResponse. The hand type
  // is intentionally a widened, index-signatured subset — assert it accepts the full spec
  // shape (the spec response is assignable INTO the hand type).
  const autopilotStatus: AutopilotStatus = {} as Schemas['AuditReadinessResponse'];

  // — the ur.bench.* namespace is ALIASED from the generated schemas, so the
  // conformance is bidirectional identity: each namespace type IS its spec component.
  const benchStatus: Schemas['BenchSuiteStatusResponse'] = {} as BenchSuiteStatus;
  const benchFreeze: Schemas['BenchDatasetFreezeResponse'] = {} as BenchDatasetFreeze;
  const benchTrigger: Schemas['BenchRunTriggerResponse'] = {} as BenchRunTrigger;
  const benchRun: Schemas['BenchRunResponse'] = {} as BenchRun;
  const benchReport: Schemas['BenchReportResponse'] = {} as BenchReport;
  const benchExpectations: Schemas['BenchExpectationsResponse'] = {} as BenchExpectations;
  const benchOutcomes: Schemas['BenchOutcomesResponse'] = {} as BenchOutcomes;
  const benchExpectInput: Schemas['BenchExpectationsRequest']['expectations'][number] =
    {} as BenchExpectationInput;
  const benchOutcomeInput: Schemas['BenchOutcomesRequest']['outcomes'][number] =
    {} as BenchOutcomeInput;
  // The `ur.bench.run(opts)` wire subset is a valid BenchRunTriggerRequest (the SDK-only
  // `suite`/`wait`/poll knobs are stripped before the POST body is built).
  const benchRunReq: Schemas['BenchRunTriggerRequest'] = {} as Omit<
    BenchRunParams,
    'suite' | 'wait' | 'pollIntervalMs' | 'waitTimeoutMs'
  >;

  // — the flywheel artifact/outcome surface is ALIASED from the generated schemas,
  // so conformance is bidirectional identity (each hand type IS its spec component).
  const createArtifactReq: Schemas['CreateArtifactRequest'] = {} as CreateArtifactParams;
  const artifact: Schemas['ArtifactSummary'] = {} as Artifact;
  const artifactEnvelope: Schemas['ArtifactEnvelope'] = {} as ArtifactEnvelope;
  const artifactList: Schemas['ArtifactListResponse'] = {} as ArtifactListResponse;
  const finalReq: Schemas['FinalRequest'] = {} as FinalParams;
  const finalResp: Schemas['FinalResponse'] = {} as FinalResponse;
  const outcomeInput: Schemas['OutcomeInput'] = {} as OutcomeInput;
  const outcomeResult: Schemas['OutcomeResult'] = {} as OutcomeResult;
  const recordOutcomesResp: Schemas['RecordOutcomesResponse'] = {} as RecordOutcomesResponse;
  const batchOutcomeInput: Schemas['BatchOutcomeInput'] = {} as BatchOutcomeInput;
  const batchOutcomesResp: Schemas['BatchOutcomesResponse'] = {} as BatchOutcomesResponse;
  const pendingResp: Schemas['PendingClaimsResponse'] = {} as PendingClaimsResponse;

  // (part 2) — flywheel status/calibration + imports are ALIASED from the generated
  // schemas (bidirectional identity), and ur.manifest IS the generated chat-request manifest shape.
  const flywheelStatus: Schemas['FlywheelStatusResponse'] = {} as FlywheelStatus;
  const flywheelUsage: Schemas['FlywheelUsageBlock'] = {} as FlywheelUsage;
  const importReq: Schemas['ImportRequest'] = {} as ImportParams;
  const importSummary: Schemas['ImportSummary'] = {} as Import;
  const importEnvelope: Schemas['ImportEnvelope'] = {} as ImportEnvelope;
  const importReport: Schemas['ImportCapabilityReport'] = {} as ImportCapabilityReport;
  const importList: Schemas['ImportListResponse'] = {} as ImportListResponse;
  const manifest: NonNullable<NonNullable<Schemas['ChatCompletionsRequest']['ur']>['manifest']> =
    {} as UrManifest;

  // The resources added for the current API are aliased from the generated schema (identity).
  const modelDetail: Schemas['ModelDetailResponse'] = {} as ModelDetail;
  const keyInfo: Schemas['KeyIntrospection'] = {} as KeyInfo;
  const evalRuns: Schemas['EvalRunListResponse'] = {} as EvalRunList;
  const reads: Schemas['ImprovementReadsResponse'] = {} as ImprovementReads;

  // — the preflight surface is ALIASED from the generated schemas
  // (bidirectional identity), so a drift in the /v1/preflight contract fails the typecheck. The one
  // SDK-typed member is the request's `messages`: the chat `ChatMessage[]`, asserted request → spec.
  const preflightReq: Schemas['PreflightRequest'] = {} as PreflightParams;
  const preflightResp: Schemas['PreflightResponse'] = {} as PreflightResponse;
  const preflightRouting: Schemas['PreflightRouting'] = {} as PreflightRouting;
  const preflightGrant: NonNullable<Schemas['PreflightResponse']['grant']> = {} as PreflightGrant;
  const preflightKnowledge: NonNullable<Schemas['PreflightResponse']['knowledge']> =
    {} as PreflightKnowledge;
  // — the preflight knowledge block carries the delivery mode `useLearned().apply()` gates on.
  const knowledgeDelivery: 'gateway_inject_after_stable_prefix' | 'off' =
    preflightKnowledge.delivery;

  // responses, the OTHER direction: everything the SPEC allows a response to carry is assignable to
  // the public type, so the public types never promise less than the contract (a value the gateway
  // may legally send must type-check in user code). Request types keep the request → spec direction.
  // Every response is asserted exactly as generated, with no exception.
  const chatRespIn: ChatCompletion = {} as Schemas['ChatCompletionsResponse'];
  const embedRespIn: CreateEmbeddingResponse = {} as Schemas['EmbeddingsResponse'];
  const modelsIn: ModelsListResponse = {} as Schemas['ModelsListResponse'];
  const feedbackIn: Feedback = {} as Schemas['FeedbackResponse'];
  const feedbackEnvelopeIn: FeedbackEnvelope = {} as Schemas['FeedbackEnvelope'];
  const generationIn: GenerationStats = {} as Schemas['GenerationStats'];
  const callTypeIn: CallType = {} as Schemas['CallTypeSummary'];
  const callTypeVersionIn: CallTypeConfigVersion = {} as NonNullable<
    Schemas['CallTypeSummary']['config']
  >;
  const urBlockIn: UrResponseBlock = {} as Schemas['UrResponseBlock'];
  const enqueueEvalRespIn: EnqueueEvalResponse = {} as Schemas['EnqueueEvalResponse'];
  const benchStatusIn: BenchSuiteStatus = {} as Schemas['BenchSuiteStatusResponse'];
  const benchFreezeIn: BenchDatasetFreeze = {} as Schemas['BenchDatasetFreezeResponse'];
  const benchTriggerIn: BenchRunTrigger = {} as Schemas['BenchRunTriggerResponse'];
  const benchRunIn: BenchRun = {} as Schemas['BenchRunResponse'];
  const benchReportIn: BenchReport = {} as Schemas['BenchReportResponse'];
  const benchExpectationsIn: BenchExpectations = {} as Schemas['BenchExpectationsResponse'];
  const benchOutcomesIn: BenchOutcomes = {} as Schemas['BenchOutcomesResponse'];
  const artifactIn: Artifact = {} as Schemas['ArtifactSummary'];
  const artifactEnvelopeIn: ArtifactEnvelope = {} as Schemas['ArtifactEnvelope'];
  const artifactListIn: ArtifactListResponse = {} as Schemas['ArtifactListResponse'];
  const finalRespIn: FinalResponse = {} as Schemas['FinalResponse'];
  const outcomeResultIn: OutcomeResult = {} as Schemas['OutcomeResult'];
  const recordOutcomesIn: RecordOutcomesResponse = {} as Schemas['RecordOutcomesResponse'];
  const batchOutcomesIn: BatchOutcomesResponse = {} as Schemas['BatchOutcomesResponse'];
  const pendingIn: PendingClaimsResponse = {} as Schemas['PendingClaimsResponse'];
  const flywheelStatusIn: FlywheelStatus = {} as Schemas['FlywheelStatusResponse'];
  const flywheelUsageIn: FlywheelUsage = {} as Schemas['FlywheelUsageBlock'];
  const importSummaryIn: Import = {} as Schemas['ImportSummary'];
  const importEnvelopeIn: ImportEnvelope = {} as Schemas['ImportEnvelope'];
  const importReportIn: ImportCapabilityReport = {} as Schemas['ImportCapabilityReport'];
  const importListIn: ImportListResponse = {} as Schemas['ImportListResponse'];
  const modelDetailIn: ModelDetail = {} as Schemas['ModelDetailResponse'];
  const keyInfoIn: KeyInfo = {} as Schemas['KeyIntrospection'];
  const evalRunsIn: EvalRunList = {} as Schemas['EvalRunListResponse'];
  const readsIn: ImprovementReads = {} as Schemas['ImprovementReadsResponse'];
  const preflightRespIn: PreflightResponse = {} as Schemas['PreflightResponse'];
  const preflightRoutingIn: PreflightRouting = {} as Schemas['PreflightRouting'];
  const preflightGrantIn: PreflightGrant = {} as NonNullable<Schemas['PreflightResponse']['grant']>;
  const preflightKnowledgeIn: PreflightKnowledge = {} as NonNullable<
    Schemas['PreflightResponse']['knowledge']
  >;
  const autopilotIn: AutopilotStatus = {} as Schemas['AuditReadinessResponse'];

  void [
    chatRespIn,
    embedRespIn,
    modelsIn,
    feedbackIn,
    feedbackEnvelopeIn,
    generationIn,
    callTypeIn,
    callTypeVersionIn,
    urBlockIn,
    enqueueEvalRespIn,
    benchStatusIn,
    benchFreezeIn,
    benchTriggerIn,
    benchRunIn,
    benchReportIn,
    benchExpectationsIn,
    benchOutcomesIn,
    artifactIn,
    artifactEnvelopeIn,
    artifactListIn,
    finalRespIn,
    outcomeResultIn,
    recordOutcomesIn,
    batchOutcomesIn,
    pendingIn,
    flywheelStatusIn,
    flywheelUsageIn,
    importSummaryIn,
    importEnvelopeIn,
    importReportIn,
    importListIn,
    modelDetailIn,
    keyInfoIn,
    evalRunsIn,
    readsIn,
    preflightRespIn,
    preflightRoutingIn,
    preflightGrantIn,
    preflightKnowledgeIn,
    autopilotIn,
  ];

  void [
    chatReq,
    embedReq,
    feedbackReq,
    callTypeReq,
    callTypeCfg,
    enqueueEvalReq,
    enqueueEvalResp,
    priorRunId,
    priorTrigger,
    priorStatus,
    chatResp,
    embedResp,
    models,
    feedback,
    feedbackEnvelope,
    generation,
    callType,
    autopilotStatus,
    benchStatus,
    benchFreeze,
    benchTrigger,
    benchRun,
    benchReport,
    benchExpectations,
    benchOutcomes,
    benchExpectInput,
    benchOutcomeInput,
    benchRunReq,
    createArtifactReq,
    artifact,
    artifactEnvelope,
    artifactList,
    finalReq,
    finalResp,
    outcomeInput,
    outcomeResult,
    recordOutcomesResp,
    batchOutcomeInput,
    batchOutcomesResp,
    pendingResp,
    flywheelStatus,
    flywheelUsage,
    importReq,
    importSummary,
    importEnvelope,
    importReport,
    importList,
    manifest,
    preflightReq,
    preflightResp,
    preflightRouting,
    preflightGrant,
    preflightKnowledge,
    knowledgeDelivery,
    modelDetail,
    keyInfo,
    evalRuns,
    reads,
  ];
}
